using System.ComponentModel.DataAnnotations; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Domain.Entities; using OrcaFacil.Domain.Enums; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Areas.Admin.Pages.Support;
[Authorize(Policy="SuperAdmin")] public sealed class DetailsModel(OrcaFacilDbContext db, OrcaFacil.Application.Abstractions.ICurrentUserService current):PageModel
{ public SupportTicket Ticket{get;private set;}=null!; public IReadOnlyList<SupportTicketMessage> Messages{get;private set;}=[]; [BindProperty,Required,StringLength(5000,MinimumLength=2)]public string Reply{get;set;}=string.Empty; [BindProperty]public SupportTicketStatus Status{get;set;}
 public async Task<IActionResult> OnGetAsync(Guid id,CancellationToken ct)=>await Load(id,ct)?Page():NotFound();
 public async Task<IActionResult> OnPostReplyAsync(Guid id,CancellationToken ct){if(!await Load(id,ct))return NotFound();if(!ModelState.IsValid)return Page();db.SupportTicketMessages.Add(new(){TicketId=id,AuthorUserId=current.UserId,Body=Reply.Trim(),IsAdminReply=true});Ticket.Status=SupportTicketStatus.WaitingForUser;Ticket.Touch();db.Notifications.Add(new(){UserId=Ticket.OpenedByUserId,Title="Seu chamado recebeu uma resposta",Message=$"{Ticket.Protocol}: {Ticket.Subject}",Category=NotificationCategory.Support,ActionUrl=$"/Support/Tickets/{id}",ActionText="Ver resposta"});await db.SaveChangesAsync(ct);return RedirectToPage(new{id});}
 public async Task<IActionResult> OnPostStatusAsync(Guid id,CancellationToken ct){if(!await Load(id,ct))return NotFound();Ticket.Status=Status;if(Status==SupportTicketStatus.Resolved)Ticket.ResolvedAt=DateTime.UtcNow;if(Status==SupportTicketStatus.Closed)Ticket.ClosedAt=DateTime.UtcNow;Ticket.Touch();await db.SaveChangesAsync(ct);return RedirectToPage(new{id});}
 async Task<bool> Load(Guid id,CancellationToken ct){Ticket=(await db.SupportTickets.SingleOrDefaultAsync(x=>x.Id==id&&!x.IsDeleted,ct))!;if(Ticket is null)return false;Messages=await db.SupportTicketMessages.AsNoTracking().Where(x=>x.TicketId==id&&!x.IsDeleted).OrderBy(x=>x.CreatedAt).ToListAsync(ct);Status=Ticket.Status;return true;}}
